<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Root component: databases -> unlock -> accounts, with a toolbar once
// unlocked. Any click resets the auto-lock idle timer.

import { t } from '@nextcloud/l10n';

import {
  activeDescriptor,
  lock,
  selectDatabase,
  selectedDatabase,
  touch,
  unlocked,
} from '../state/session';
import AccountsView from './AccountsView.vue';
import DatabasesView from './DatabasesView.vue';
import ExportButton from './ExportButton.vue';
import SyncButton from './SyncButton.vue';
import UnlockView from './UnlockView.vue';

function onLock(): void {
  lock();
}

/** Return to the database list (locking first when a database is open). */
function onChangeDatabase(): void {
  lock();
  selectDatabase(null);
}
</script>

<template>
  <div
    class="upm-app"
    style="padding: 20px"
    @click="touch"
    @keydown="touch"
  >
    <DatabasesView v-if="!selectedDatabase" />
    <UnlockView v-else-if="!unlocked" />
    <template v-else>
      <div style="display: flex; gap: 8px; align-items: center; margin-bottom: 12px">
        <button type="button" class="button" @click="onLock">{{ t('upm', 'Lock') }}</button>
        <SyncButton />
        <ExportButton />
        <button type="button" class="button" @click="onChangeDatabase">
          {{ t('upm', 'Change database') }}
        </button>
      </div>
      <p v-if="activeDescriptor" style="opacity: 0.7; margin-top: 0">
        {{ activeDescriptor.label }}
        <span v-if="activeDescriptor.path !== activeDescriptor.label">
          — {{ activeDescriptor.path }}
        </span>
      </p>
      <AccountsView />
    </template>
  </div>
</template>
